        on: JSONValue? = null,
        extra: Map<String, JSONValue>? = null,
    ): JSONValue =
        this.engine.command(
            "file.useProxy",
            extra,
            "items" to items?.jsonValue,
            "item" to item?.jsonValue,
            "on" to on?.jsonValue,
        )
}
